sys_script_client.script:
function onSubmit() {

    if (g_form.getValue('status') !== 'approved') {
        return;
    }

    g_form.clearMessages();

    var checkFields = {
        attendance_ok: 'Attendance Ok',
        fee_ok: 'Fee Ok'
    };
    var firstInvalidField = '';

    for (var field in checkFields) {
        if (g_form.getValue(field) !== 'true') {
            g_form.addErrorMessage(checkFields[field] + ' must be checked before approving.');
            firstInvalidField = firstInvalidField || field;
        }
    }

    if (firstInvalidField) {
        g_form.getControl(firstInvalidField).focus();
        return false;
    }
}
